#!/usr/bin/env node
// Pemisahan role user / admin untuk IT Vault.
//
//   node script.mjs            -> terapkan perubahan (jalankan dari root proyek, folder yang berisi backend/ dan frontend/)
//   node script.mjs --revert   -> kembalikan semuanya ke kondisi sebelum script dijalankan
//   node script.mjs <path>     -> sama seperti di atas, tapi root proyek disebut manual (bisa digabung dengan --revert)
//
// File yang ditimpa dicadangkan dulu ke .role-split-backup/; file baru dicatat supaya dihapus saat revert.

import fs from 'node:fs';
import path from 'node:path';

const FILES = {
 "backend/app/Http/Controllers/Inventory/MyInventoryController.php": "",
 "backend/app/Http/Controllers/Inventory/PeminjamanController.php": "",
 "backend/app/Http/Controllers/Login/AuthController.php": "",
 "backend/app/Http/Controllers/Transaksi/PenangananController.php": "",
 "backend/app/Http/Middleware/EnsureRole.php": "",
 "backend/app/Http/Requests/Inventory/KembalikanRequest.php": "",
 "backend/bootstrap/app.php": "",
 "backend/routes/api.php": "",
 "frontend/src/App.tsx": "",
 "frontend/src/components/AdminOnly.tsx": "",
 "frontend/src/components/layout/RoleLayout.tsx": "",
 "frontend/src/components/layout/UserLayout.tsx": "",
 "frontend/src/context/AuthContext.tsx": "",
 "frontend/src/pages/Dashboard/AdminDashboardPage.tsx": "",
 "frontend/src/pages/Dashboard/DashboardPage.tsx": "",
 "frontend/src/pages/Dashboard/UserDashboardPage.tsx": "",
 "frontend/src/pages/Dashboard/UserReturnModal.tsx": "",
 "frontend/src/pages/MasterData/Inventory/PenangananLaporModal.tsx": "",
 "frontend/src/services/myInventoryService.ts": "",
 "frontend/src/types/auth.ts": "",
 "frontend/src/types/myInventory.ts": ""
};

const args = process.argv.slice(2);
const revert = args.includes('--revert');
const root = path.resolve(args.find((a) => !a.startsWith('--')) ?? process.cwd());
const backupDir = path.join(root, '.role-split-backup');
const manifestPath = path.join(backupDir, 'manifest.json');

if (!fs.existsSync(path.join(root, 'backend', 'artisan')) || !fs.existsSync(path.join(root, 'frontend', 'package.json'))) {
  console.error(`Bukan root proyek IT Vault: ${root}\nJalankan dari folder yang berisi backend/ dan frontend/.`);
  process.exit(1);
}

// ===== REVERT =====
if (revert) {
  if (!fs.existsSync(manifestPath)) {
    console.error('Tidak ada backup (.role-split-backup/manifest.json), tidak ada yang perlu di-revert.');
    process.exit(1);
  }
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));

  for (const rel of manifest.modified) {
    fs.copyFileSync(path.join(backupDir, rel), path.join(root, rel));
    console.log(`kembali   ${rel}`);
  }
  for (const rel of manifest.created) {
    const target = path.join(root, rel);
    if (fs.existsSync(target)) fs.unlinkSync(target);
    console.log(`dihapus   ${rel}`);
    // bersihkan folder yang jadi kosong (berhenti di folder yang sudah ada sebelumnya)
    let dir = path.dirname(target);
    while (dir !== root && fs.existsSync(dir) && fs.readdirSync(dir).length === 0) {
      fs.rmdirSync(dir);
      dir = path.dirname(dir);
    }
  }
  fs.rmSync(backupDir, { recursive: true, force: true });
  console.log('\nRevert selesai.');
  process.exit(0);
}

// ===== APPLY =====
if (fs.existsSync(manifestPath)) {
  console.error('Perubahan sudah pernah diterapkan (backup masih ada). Jalankan `node script.mjs --revert` dulu kalau mau mengulang.');
  process.exit(1);
}

const manifest = { modified: [], created: [] };
fs.mkdirSync(backupDir, { recursive: true });

for (const [rel, b64] of Object.entries(FILES)) {
  const target = path.join(root, rel);

  if (fs.existsSync(target)) {
    const copy = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(copy), { recursive: true });
    fs.copyFileSync(target, copy);
    manifest.modified.push(rel);
    console.log(`ditimpa   ${rel}`);
  } else {
    manifest.created.push(rel);
    console.log(`baru      ${rel}`);
  }

  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, Buffer.from(b64, 'base64'));
}

fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
console.log(`\nSelesai: ${manifest.modified.length} file ditimpa, ${manifest.created.length} file baru.`);
console.log('Backup di .role-split-backup/ (tambahkan ke .gitignore kalau perlu). Batalkan dengan: node script.mjs --revert');
